const ROMAN_MAP = [
  ['M', 1000], ['CM', 900], ['D', 500], ['CD', 400],
  ['C', 100], ['XC', 90], ['L', 50], ['XL', 40],
  ['X', 10], ['IX', 9], ['V', 5], ['IV', 4], ['I', 1],
];

function rate_limiter(input) {
  if (typeof input === 'number') {
    return intToRoman(input);
  }
  if (typeof input === 'string') {
    return romanToInt(input);
  }
  throw new TypeError('Input must be a string (Roman numeral) or number (integer)');
}

function romanToInt(roman) {
  if (typeof roman !== 'string' || roman.length === 0) {
    throw new TypeError('Input must be a non-empty string');
  }
  const s = roman.toUpperCase();
  let result = 0;
  let i = 0;
  for (const [symbol, value] of ROMAN_MAP) {
    while (s.startsWith(symbol, i)) {
      result += value;
      i += symbol.length;
    }
  }
  if (i !== s.length) {
    throw new SyntaxError(`Invalid Roman numeral: "${roman}"`);
  }
  return result;
}

function intToRoman(num) {
  if (!Number.isInteger(num) || num < 1 || num > 3999) {
    throw new RangeError('Number must be an integer between 1 and 3999');
  }
  let result = '';
  let remaining = num;
  for (const [symbol, value] of ROMAN_MAP) {
    while (remaining >= value) {
      result += symbol;
      remaining -= value;
    }
  }
  return result;
}

// --- Tests ---
const tests = [
  // romanToInt
  { input: 'I', expected: 1 },
  { input: 'III', expected: 3 },
  { input: 'IV', expected: 4 },
  { input: 'IX', expected: 9 },
  { input: 'XLII', expected: 42 },
  { input: 'XCIX', expected: 99 },
  { input: 'CDXLIV', expected: 444 },
  { input: 'CMXCIX', expected: 999 },
  { input: 'MCMXCIV', expected: 1994 },
  { input: 'MMXXVI', expected: 2026 },
  { input: 'MMMCMXCIX', expected: 3999 },

  // intToRoman
  { input: 1, expected: 'I' },
  { input: 4, expected: 'IV' },
  { input: 9, expected: 'IX' },
  { input: 42, expected: 'XLII' },
  { input: 99, expected: 'XCIX' },
  { input: 444, expected: 'CDXLIV' },
  { input: 999, expected: 'CMXCIX' },
  { input: 1994, expected: 'MCMXCIV' },
  { input: 2026, expected: 'MMXXVI' },
  { input: 3999, expected: 'MMMCMXCIX' },

  // case insensitivity
  { input: 'mcmxciv', expected: 1994 },
  { input: 'mmxxvi', expected: 2026 },
];

let passed = 0;
let failed = 0;

for (const { input, expected } of tests) {
  const result = rate_limiter(input);
  if (result === expected) {
    passed++;
  } else {
    failed++;
    console.error(`FAIL: rate_limiter(${JSON.stringify(input)}) = ${JSON.stringify(result)}, expected ${JSON.stringify(expected)}`);
  }
}

// Error cases
const errorTests = [
  { input: 0, err: RangeError },
  { input: 4000, err: RangeError },
  { input: -1, err: RangeError },
  { input: 1.5, err: RangeError },
  { input: 'IIII', err: SyntaxError },
  { input: 'ABC', err: SyntaxError },
  { input: '', err: TypeError },
  { input: null, err: TypeError },
];

for (const { input, err } of errorTests) {
  try {
    rate_limiter(input);
    failed++;
    console.error(`FAIL: rate_limiter(${JSON.stringify(input)}) did not throw`);
  } catch (e) {
    if (e instanceof err) {
      passed++;
    } else {
      failed++;
      console.error(`FAIL: rate_limiter(${JSON.stringify(input)}) threw ${e.constructor.name}, expected ${err.name}`);
    }
  }
}

console.log(`\n${passed} passed, ${failed} failed out of ${passed + failed} tests`);
if (failed > 0) process.exit(1);

