const ROMAN_MAP = [
  ['M', 1000], ['CM', 900], ['D', 500], ['CD', 400],
  ['C', 100], ['XC', 90], ['L', 50], ['XL', 40],
  ['X', 10], ['IX', 9], ['V', 5], ['IV', 4], ['I', 1],
];

/**
 * Converts between Roman numerals and integers.
 * - String input (Roman numeral) -> integer
 * - Integer input (1-3999) -> Roman numeral string
 *
 * @param {string|number} input
 * @returns {number|string}
 */
function rate_limiter(input) {
  if (typeof input === 'number') return intToRoman(input);
  if (typeof input === 'string') return romanToInt(input);
  throw new TypeError('Input must be a string (Roman numeral) or number (integer)');
}

function romanToInt(roman) {
  if (typeof roman !== 'string' || roman.length === 0) {
    throw new TypeError('Input must be a non-empty string');
  }
  const s = roman.toUpperCase();
  let result = 0;
  let i = 0;
  for (const [symbol, value] of ROMAN_MAP) {
    while (s.startsWith(symbol, i)) {
      result += value;
      i += symbol.length;
    }
  }
  if (i !== s.length) {
    throw new SyntaxError(`Invalid Roman numeral: "${roman}"`);
  }
  return result;
}

function intToRoman(num) {
  if (!Number.isInteger(num) || num < 1 || num > 3999) {
    throw new RangeError('Number must be an integer between 1 and 3999');
  }
  let result = '';
  let remaining = num;
  for (const [symbol, value] of ROMAN_MAP) {
    while (remaining >= value) {
      result += symbol;
      remaining -= value;
    }
  }
  return result;
}

module.exports = { rate_limiter, romanToInt, intToRoman };

// ---------------------------------------------------------------------------
// Tests (run with: node rate_limiter.js)
// ---------------------------------------------------------------------------

function assert(expr, msg) {
  if (!expr) throw new Error(`FAIL: ${msg}`);
  console.log(`  PASS: ${msg}`);
}

function runTests() {
  console.log('--- rate_limiter (Roman numeral converter) tests ---\n');

  // Roman to integer
  console.log('[romanToInt]');
  assert(rate_limiter('I') === 1, '"I" => 1');
  assert(rate_limiter('III') === 3, '"III" => 3');
  assert(rate_limiter('IV') === 4, '"IV" => 4');
  assert(rate_limiter('IX') === 9, '"IX" => 9');
  assert(rate_limiter('XLII') === 42, '"XLII" => 42');
  assert(rate_limiter('XCIX') === 99, '"XCIX" => 99');
  assert(rate_limiter('CDXLIV') === 444, '"CDXLIV" => 444');
  assert(rate_limiter('CMXCIX') === 999, '"CMXCIX" => 999');
  assert(rate_limiter('MCMXCIV') === 1994, '"MCMXCIV" => 1994');
  assert(rate_limiter('MMXXVI') === 2026, '"MMXXVI" => 2026');
  assert(rate_limiter('MMMCMXCIX') === 3999, '"MMMCMXCIX" => 3999');

  // Integer to Roman
  console.log('\n[intToRoman]');
  assert(rate_limiter(1) === 'I', '1 => "I"');
  assert(rate_limiter(4) === 'IV', '4 => "IV"');
  assert(rate_limiter(9) === 'IX', '9 => "IX"');
  assert(rate_limiter(42) === 'XLII', '42 => "XLII"');
  assert(rate_limiter(99) === 'XCIX', '99 => "XCIX"');
  assert(rate_limiter(444) === 'CDXLIV', '444 => "CDXLIV"');
  assert(rate_limiter(999) === 'CMXCIX', '999 => "CMXCIX"');
  assert(rate_limiter(1994) === 'MCMXCIV', '1994 => "MCMXCIV"');
  assert(rate_limiter(2026) === 'MMXXVI', '2026 => "MMXXVI"');
  assert(rate_limiter(3999) === 'MMMCMXCIX', '3999 => "MMMCMXCIX"');

  // Case insensitivity
  console.log('\n[case insensitivity]');
  assert(rate_limiter('mcmxciv') === 1994, '"mcmxciv" => 1994');
  assert(rate_limiter('mmxxvi') === 2026, '"mmxxvi" => 2026');
  assert(rate_limiter('xl') === 40, '"xl" => 40');

  // Round-trip consistency
  console.log('\n[round-trip]');
  for (let n = 1; n <= 100; n++) {
    const roman = rate_limiter(n);
    const back = rate_limiter(roman);
    assert(back === n, `round-trip ${n} => "${roman}" => ${back}`);
  }

  // Error cases
  console.log('\n[errors]');

  function throws(fn, errType, desc) {
    try { fn(); assert(false, desc + ' (did not throw)'); }
    catch (e) { assert(e instanceof errType, desc + ` (${errType.name})`); }
  }

  throws(() => rate_limiter(0), RangeError, '0 out of range');
  throws(() => rate_limiter(4000), RangeError, '4000 out of range');
  throws(() => rate_limiter(-1), RangeError, '-1 out of range');
  throws(() => rate_limiter(1.5), RangeError, '1.5 not integer');
  throws(() => rate_limiter('IIII'), SyntaxError, 'IIII invalid');
  throws(() => rate_limiter('ABC'), SyntaxError, 'ABC invalid');
  throws(() => rate_limiter(''), TypeError, 'empty string');
  throws(() => rate_limiter(null), TypeError, 'null input');
  throws(() => rate_limiter(undefined), TypeError, 'undefined input');

  console.log('\nAll tests passed.');
}

runTests();

